205	    /**
206	     * Required national-number length per country calling code. When the normalized E.164 number
207	     * begins with one of these codes, the digits that follow must number exactly the mapped value:
208	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Codes absent from
209	     * this map carry no per-country length rule beyond the generic E.164 8-to-15-digit bound.
210	     */
211	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
212	        "+61", 9,
213	        "+1", 10);
214	
215	    /**
216	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
217	     * stripped. When a leading '+' (with its country code) is present it is kept as-is; otherwise
218	     * the country code '+61' is assumed and a single leading '0' is dropped from the national
219	     * digits. The result must be a '+' followed by 8 to 15 digits, so e.g. '0412 345 678' is
220	     * stored as '+61412345678'. When the country code has a known national-number length ('+61'
221	     * requires 9 national digits, '+1' requires 10) the national digits must match it exactly. A
222	     * value that cannot form a valid E.164 number, or whose national length is wrong for its
223	     * country, is rejected via {@link InvalidTelephoneException}, which the exception handler
224	     * translates to a 400.
225	     */
226	    private static String normalizeTelephone(String telephone) {
227	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()\\[\\]]", "");
228	        String e164;
229	        if (cleaned.startsWith("+")) {
230	            e164 = cleaned;
231	        } else {
232	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
233	            e164 = "+61" + national;
234	        }
235	        if (!E164_PATTERN.matcher(e164).matches()) {
236	            throw new InvalidTelephoneException(telephone);
237	        }
238	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
239	            String code = rule.getKey();
240	            if (e164.startsWith(code)) {
241	                int nationalLength = e164.length() - code.length();
242	                if (nationalLength != rule.getValue()) {
243	                    throw new InvalidTelephoneException(telephone);
244	                }
245	                break;
246	            }
247	        }
248	        return e164;
249	    }
250	
251	    /**
252	     * Matches a well-formed postcode: exactly four digits.
253	     */
254	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("\\d{4}");
255	
256	    /**
257	     * The canonical region for each city that has one. A city absent from this table has no known
258	     * region and so accepts any 4-digit postcode. This is the same fixed city-to-region table used
259	     * to derive an owner's locality.
260	     */
261	    private static final Map<String, String> CITY_REGION = Map.of(
262	        "Sydney", "NSW",
263	        "Melbourne", "VIC",
264	        "Brisbane", "QLD");
265	
266	    /**
267	     * The inclusive 4-digit postcode range for each region, as {@code {low, high}}: NSW 2000-2099,
268	     * VIC 3000-3099, QLD 4000-4099.
269	     */
270	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
271	        "NSW", new int[] {2000, 2099},
272	        "VIC", new int[] {3000, 3099},
273	        "QLD", new int[] {4000, 4099});
274	
275	    /**
276	     * Validates an owner's optional postcode. A {@code null} postcode is left as-is (the field is
277	     * optional). When present it must be exactly four digits; and when the owner's city maps to a
278	     * known region it must fall within that region's inclusive postcode range (NSW 2000-2099, VIC
279	     * 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An
280	     * invalid or out-of-range value is rejected via {@link InvalidPostcodeException}, which the
281	     * exception handler translates to a 400.
282	     */
283	    private static void validatePostcode(String city, String postcode) {
284	        if (postcode == null) {
285	            return;
286	        }
287	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
288	            throw new InvalidPostcodeException(postcode);
289	        }
290	        String region = CITY_REGION.get(city);
291	        if (region == null) {
292	            return;
293	        }
294	        int[] range = REGION_POSTCODES.get(region);
295	        int value = Integer.parseInt(postcode);
296	        if (value < range[0] || value > range[1]) {
297	            throw new InvalidPostcodeException(postcode);
298	        }
299	    }
300	
301	    /**
302	     * A pragmatic syntactic email check: a non-empty local part, an {@code @}, and a domain that
303	     * carries at least one dot, with no whitespace anywhere. Deliberately permissive — it accepts
304	     * ordinary addresses while rejecting obvious non-addresses such as one lacking an {@code @}.
305	     */
306	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
307	
308	    /**
309	     * Disposable-email domains that an owner's email may not use. An address whose domain (the part
310	     * after the final {@code @}, compared case-insensitively) is one of these is rejected. Kept as a
311	     * fixed set so the block list is explicit and easy to extend.
312	     */
313	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
314	        "mailinator.com",
315	        "tempmail.com",
316	        "guerrillamail.com");
317	
318	    /**
319	     * Normalizes an optional owner email. A {@code null} email is left as-is (the field is
320	     * optional). When present it must be a syntactically valid address whose domain is not on the
321	     * disposable-domain block list; a valid value is lower-cased so it is stored and returned in
322	     * canonical form. An invalid or disposable-domain value is rejected via
323	     * {@link InvalidEmailException}, which the exception handler translates to a 400.
324	     */
325	    private static String normalizeEmail(String email) {
326	        if (email == null) {
327	            return null;
328	        }
329	        if (!EMAIL_PATTERN.matcher(email).matches()) {
330	            throw new InvalidEmailException(email);
331	        }
332	        String normalized = email.toLowerCase(Locale.ROOT);
333	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
334	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
335	            throw new InvalidEmailException(email);
336	        }
337	        return normalized;
338	    }
339	
340	    /**
341	     * The single derived identity of an owner: the 64-character lower-case SHA-256 hex digest over
342	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, into which all
343	     * duplicate detection is consolidated. Two owners are the same identity only when this whole key
344	     * matches: because the normalized telephone is part of the pre-image, two owners who share a
345	     * surname (same soundex) and postcode but carry different telephones have different identity
346	     * keys. A {@code null} email contributes an empty middle segment. This is the value returned to
347	     * callers as {@code identityKey}.
348	     */
349	    private static String identityKeyFor(String normalizedTelephone, String normalizedEmail, String lastName) {
350	        String preimage = normalizedTelephone + "|" + (normalizedEmail == null ? "" : normalizedEmail)
351	            + "|" + soundex(lastName);
352	        return sha256Hex(preimage);
353	    }
354	
355	    /**
356	     * The American Soundex code of a name: its first letter followed by up to three digits encoding
357	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
358	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent so
359	     * consonants they separate are still treated as adjacent. The result is padded with zeros to
360	     * exactly four characters. A {@code null} or letterless name yields the empty string.
361	     */
362	    private static String soundex(String name) {
363	        if (name == null) {
364	            return "";
365	        }
366	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
367	        if (letters.isEmpty()) {
368	            return "";
369	        }
370	        StringBuilder code = new StringBuilder();
371	        code.append(letters.charAt(0));
372	        char prev = soundexCode(letters.charAt(0));
373	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
374	            char c = letters.charAt(i);
375	            if (c == 'H' || c == 'W') {
376	                continue;
377	            }
378	            char digit = soundexCode(c);
379	            if (digit != '0' && digit != prev) {
380	                code.append(digit);
381	            }
382	            prev = digit;
383	        }
384	        while (code.length() < 4) {
385	            code.append('0');
386	        }
387	        return code.toString();
388	    }
