390	    /**
391	     * The Soundex digit for a single upper-case letter, or {@code '0'} for a vowel, y, h or w (which
392	     * carry no code).
393	     */
394	    private static char soundexCode(char c) {
395	        return switch (c) {
396	            case 'B', 'F', 'P', 'V' -> '1';
397	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
398	            case 'D', 'T' -> '3';
399	            case 'L' -> '4';
400	            case 'M', 'N' -> '5';
401	            case 'R' -> '6';
402	            default -> '0';
403	        };
404	    }
