406	    /**
407	     * The full lower-case SHA-256 hex digest (64 characters) of the UTF-8 bytes of {@code value}.
408	     */
409	    private static String sha256Hex(String value) {
410	        try {
411	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
412	            StringBuilder sb = new StringBuilder(digest.length * 2);
413	            for (byte b : digest) {
414	                sb.append(String.format("%02x", b));
415	            }
416	            return sb.toString();
417	        } catch (NoSuchAlgorithmException ex) {
418	            throw new IllegalStateException("SHA-256 not available", ex);
419	        }
420	    }
