422	    /**
423	     * Rejects a create whose derived identity collides with an existing owner's, reported via
424	     * {@link DuplicateTelephoneException} which the handler translates to a 409. Duplicate detection
425	     * is now the single identity key: the new owner's {@link #identityKeyFor identityKey} (the
426	     * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}) is
427	     * compared against each existing owner's, ignoring owners flagged deleted. The email-domain
428	     * block list has already been applied while normalizing the email, so it takes effect first. An
429	     * existing telephone that cannot form a valid E.164 number is skipped rather than colliding.
430	     * Because the telephone is part of the key, two owners with the same surname and postcode but
431	     * different telephones no longer collide here - they are surfaced as a soft match instead. The
432	     * former separate telephone, email and household 409 blocks are all subsumed by this key.
433	     */
434	    private void rejectDuplicateIdentity(String normalizedTelephone, String normalizedEmail, String lastName) {
435	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
436	        for (Owner existing : this.clinicService.findAllOwners()) {
437	            if (existing.isDeleted()) {
438	                continue;
439	            }
440	            String existingTelephone;
441	            try {
442	                existingTelephone = normalizeTelephone(existing.getTelephone());
443	            } catch (InvalidTelephoneException ex) {
444	                continue;
445	            }
446	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
447	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
448	            if (identityKey.equals(existingKey)) {
449	                throw new DuplicateTelephoneException(normalizedTelephone);
450	            }
451	        }
452	    }
