454	    /**
455	     * Collapses a value for household comparison: leading and trailing whitespace is trimmed, any
456	     * internal run of whitespace is reduced to a single space, and the result is lower-cased. This
457	     * is how both {@code lastName} and {@code address} are compared so that differences of case or
458	     * spacing do not defeat the duplicate-household check.
459	     */
460	    private static String collapse(String value) {
461	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
462	    }
463	
464	    /**
465	     * Normalizes an owner's address into a canonical form applied on every create: leading and
466	     * trailing whitespace is trimmed, any internal run of whitespace is reduced to a single space,
467	     * the value is upper-cased, and common street-type abbreviations are expanded on a per-word
468	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The result is stored
469	     * and returned, and is the form every address comparison (duplicate-household detection and the
470	     * shared {@code householdId}) uses. A {@code null} or whitespace-only input normalizes to the
471	     * empty string, which the required-field guard then rejects. The transformation is idempotent,
472	     * so normalizing an already-normalized address is a no-op.
473	     */
474	    private static String normalizeAddress(String address) {
475	        if (address == null) {
476	            return "";
477	        }
478	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
479	        if (collapsed.isEmpty()) {
480	            return "";
481	        }
482	        String[] tokens = collapsed.split(" ");
483	        StringBuilder sb = new StringBuilder(collapsed.length());
484	        for (int i = 0; i < tokens.length; i++) {
485	            String token = tokens[i];
486	            switch (token) {
487	                case "ST" -> token = "STREET";
488	                case "RD" -> token = "ROAD";
489	                case "AVE" -> token = "AVENUE";
490	                default -> {
491	                }
492	            }
493	            if (i > 0) {
494	                sb.append(' ');
495	            }
496	            sb.append(token);
497	        }
498	        return sb.toString();
499	    }
