501	    /**
502	     * Derives an owner's region code from its postcode, falling back to its city. A present postcode
503	     * that falls in a known region's inclusive 4-digit range wins (NSW 2000-2099, VIC 3000-3099, QLD
504	     * 4000-4099); otherwise the fixed city-to-region table is consulted (Sydney -> NSW, Melbourne ->
505	     * VIC, Brisbane -> QLD); a value resolved by neither is {@code "UNKNOWN"}. This is the single
506	     * region derivation shared by the {@code memberId} and the owner's locality.
507	     */
508	    private static String deriveRegion(String city, String postcode) {
509	        if (postcode != null) {
510	            try {
511	                int pc = Integer.parseInt(postcode.trim());
512	                for (Map.Entry<String, int[]> range : REGION_POSTCODES.entrySet()) {
513	                    int[] bounds = range.getValue();
514	                    if (pc >= bounds[0] && pc <= bounds[1]) {
515	                        return range.getKey();
516	                    }
517	                }
518	            } catch (NumberFormatException ignored) {
519	                // not a numeric postcode; fall back to the city-to-region table
520	            }
521	        }
522	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
523	    }
