525	    /**
526	     * Builds the {@code memberId} for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}
527	     * where {@code REGION} is the region code derived from the owner's postcode (falling back to its
528	     * city), {@code FY} is the 2-digit fiscal year of the {@code registrationDate} (matching the owner's
529	     * {@code fiscalYear}), {@code HASH8} is the first 8 upper-case hex characters of SHA-256 over
530	     * {@code normalizedTelephone + lastName} (the same HASH8 used by the region-and-hash identity), and
531	     * {@code CHK} is a single Luhn check digit computed over the digits of {@code <REGION><FY><HASH8>}
532	     * (e.g. {@code 'NSW271A2B3C4D5'}). This is a stable identity: it carries no sequence number and
533	     * depends only on the owner's own region, fiscal year, telephone and surname.
534	     */
535	    private static String memberIdFor(String region, LocalDate registrationDate,
536	                                      String normalizedTelephone, String lastName) {
537	        String fy = String.format("%02d", fiscalYearOf(registrationDate) % 100);
538	        String hash8 = sha256HexPrefix(normalizedTelephone + lastName, 8);
539	        String base = region + fy + hash8;
540	        return base + luhnCheckDigit(base);
541	    }
542	
543	    /**
544	     * The single Luhn check digit (0-9) computed over the digits contained in {@code value};
545	     * non-digit characters are ignored.
546	     */
547	    private static int luhnCheckDigit(String value) {
548	        int sum = 0;
549	        boolean dbl = true;
550	        for (int i = value.length() - 1; i >= 0; i--) {
551	            char c = value.charAt(i);
552	            if (c < '0' || c > '9') {
553	                continue;
554	            }
555	            int d = c - '0';
556	            if (dbl) {
557	                d *= 2;
558	                if (d > 9) {
559	                    d -= 9;
560	                }
561	            }
562	            sum += d;
563	            dbl = !dbl;
564	        }
565	        return (10 - (sum % 10)) % 10;
566	    }
