568	    /**
569	     * De-duplicates a freshly computed {@code memberId} against the ids already carried by existing
570	     * owners. When the base id is unused it is returned unchanged; otherwise {@code '-<n>'} is appended
571	     * with the smallest {@code n} of 2 or more that yields an id no existing owner already holds. The
572	     * count reflects the state prior to this create.
573	     */
574	    private String deduplicateMemberId(String baseId) {
575	        Set<String> existingIds = new HashSet<>();
576	        for (Owner existing : this.clinicService.findAllOwners()) {
577	            String id = existing.getMemberId();
578	            if (id != null) {
579	                existingIds.add(id);
580	            }
581	        }
582	        if (!existingIds.contains(baseId)) {
583	            return baseId;
584	        }
585	        int n = 2;
586	        while (existingIds.contains(baseId + "-" + n)) {
587	            n++;
588	        }
589	        return baseId + "-" + n;
590	    }
