592	    /**
593	     * Returns the first {@code hexChars} upper-case hex characters of the SHA-256 digest of the UTF-8
594	     * bytes of {@code value}.
595	     */
596	    private static String sha256HexPrefix(String value, int hexChars) {
597	        try {
598	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
599	            StringBuilder sb = new StringBuilder(hexChars);
600	            for (byte b : digest) {
601	                if (sb.length() >= hexChars) {
602	                    break;
603	                }
604	                sb.append(String.format("%02X", b));
605	            }
606	            return sb.substring(0, hexChars);
607	        } catch (NoSuchAlgorithmException ex) {
608	            throw new IllegalStateException("SHA-256 not available", ex);
609	        }
610	    }
