622	    /**
623	     * Derives the stable {@code householdId} for an owner from the collapsed {@code lastName} and
624	     * its {@code postcode} - the same pair used to detect a shared household. It is the first 12
625	     * lower-case hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Because
626	     * it is a pure function of that pair, every owner in the same household - whether created first
627	     * or joining later via {@code sharesHousehold} - receives the identical, non-blank identifier
628	     * without needing to read any other owner's value. A {@code null} postcode contributes an empty
629	     * segment.
630	     */
631	    private static String householdIdFor(String lastName, String postcode) {
632	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
633	        try {
634	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
635	            StringBuilder sb = new StringBuilder(12);
636	            for (byte b : digest) {
637	                if (sb.length() >= 12) {
638	                    break;
639	                }
640	                sb.append(String.format("%02x", b));
641	            }
642	            return sb.substring(0, 12);
643	        } catch (NoSuchAlgorithmException ex) {
644	            throw new IllegalStateException("SHA-256 not available", ex);
645	        }
646	    }
