648	    /**
649	     * Counts the existing owners who already share the given {@code firstName} and {@code lastName},
650	     * compared case-insensitively. This is evaluated before the new owner is saved, so it reflects
651	     * the state prior to this create and is stored on the owner as its {@code namesakeCount}.
652	     */
653	    private int countNamesakes(String firstName, String lastName) {
654	        int count = 0;
655	        for (Owner existing : this.clinicService.findAllOwners()) {
656	            if (firstName.equalsIgnoreCase(existing.getFirstName())
657	                && lastName.equalsIgnoreCase(existing.getLastName())) {
658	                count++;
659	            }
660	        }
661	        return count;
662	    }
