664	    /**
665	     * Counts the members of the household the new owner will belong to, as it stands after this
666	     * create. Every existing owner carrying the same {@code householdId} is counted, and the new
667	     * owner itself is added, so a value of 3 or more means the owner joins a household of at least
668	     * three members. This is evaluated with the new owner's {@code householdId} already set and is
669	     * stored on the owner as its {@code householdMemberCount}.
670	     */
671	    private int countHouseholdMembers(String householdId) {
672	        int count = 1;
673	        for (Owner existing : this.clinicService.findAllOwners()) {
674	            if (householdId.equals(existing.getHouseholdId())) {
675	                count++;
676	            }
677	        }
678	        return count;
