681	    /**
682	     * Finds an existing owner that makes the new owner a <em>possible</em> (soft) duplicate: one
683	     * that is not a hard identity collision but whose {@code lastName} has the same
684	     * {@link #soundex soundex} code as the new owner's and whose {@code postcode} matches, while its
685	     * {@link #identityKeyFor identityKey} differs. The new owner's postcode must be present for a
686	     * soft match to be possible. When several existing owners qualify the one with the lowest id is
687	     * chosen. Returns the matching owner's id, or {@code null} when there is no soft match. This is
688	     * evaluated after the hard-duplicate check has already passed, so any surviving owner sharing the
689	     * surname's soundex and postcode necessarily has a different identity key (typically a different
690	     * telephone). A caller that declares {@code sharesHousehold} is deliberately joining an existing
691	     * household, so it is not flagged as a suspected duplicate.
692	     */
693	    private Integer findPossibleDuplicateOf(OwnerFieldsDto ownerFieldsDto, String normalizedTelephone,
694	                                            String normalizedEmail) {
695	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
696	            return null;
697	        }
698	        String postcode = ownerFieldsDto.getPostcode();
699	        if (postcode == null) {
700	            return null;
701	        }
702	        String lastName = ownerFieldsDto.getLastName();
703	        if (lastName == null) {
704	            return null;
705	        }
706	        String identityKey = identityKeyFor(normalizedTelephone, normalizedEmail, lastName);
707	        String soundex = soundex(lastName);
708	        Integer matchId = null;
709	        for (Owner existing : this.clinicService.findAllOwners()) {
710	            if (existing.isDeleted()) {
711	                continue;
712	            }
713	            if (!soundex.equals(soundex(existing.getLastName()))) {
714	                continue;
715	            }
716	            if (!postcode.equals(existing.getPostcode())) {
717	                continue;
718	            }
719	            String existingTelephone;
720	            try {
721	                existingTelephone = normalizeTelephone(existing.getTelephone());
722	            } catch (InvalidTelephoneException ex) {
723	                continue;
724	            }
725	            String existingEmail = existing.getEmail() == null ? null : existing.getEmail().toLowerCase(Locale.ROOT);
726	            String existingKey = identityKeyFor(existingTelephone, existingEmail, existing.getLastName());
727	            if (identityKey.equals(existingKey)) {
728	                continue;
729	            }
730	            if (existing.getId() != null && (matchId == null || existing.getId() < matchId)) {
731	                matchId = existing.getId();
732	            }
733	        }
734	        return matchId;
735	    }
