737	    /**
738	     * The tenure, in elapsed fiscal years, that an owner must exceed before its tenure contributes
739	     * membership points. Tenure is measured from the owner's {@code registrationDate}, so a newly
740	     * created owner (whose tenure is zero) never satisfies this and thus never earns the tenure
741	     * points on create.
742	     */
743	    private static final int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
744	
745	    /**
746	     * The household size (number of members) at or above which an owner earns the household points.
747	     */
748	    private static final int HOUSEHOLD_POINTS_THRESHOLD = 3;
749	
750	    /**
751	     * Computes the {@code membershipPoints} for an owner. Points start at 0, gain 2 when an email is
752	     * present, gain 1 when the owner's {@code namesakeCount} is 0, gain 2 when the owner's household
753	     * has {@value #HOUSEHOLD_POINTS_THRESHOLD} or more members, and gain 3 when the owner's tenure
754	     * (elapsed fiscal years since its {@code registrationDate}) exceeds
755	     * {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS}. Because a newly created owner has zero tenure,
756	     * the tenure points never apply on create.
757	     * Evaluated after the owner's email, namesakeCount, householdMemberCount and registrationDate
758	     * have been set.
759	     */
760	    private static int membershipPointsFor(Owner owner) {
761	        int points = 0;
762	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
763	            points += 2;
764	        }
765	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
766	            points += 1;
767	        }
768	        if (owner.getHouseholdMemberCount() != null
769	            && owner.getHouseholdMemberCount() >= HOUSEHOLD_POINTS_THRESHOLD) {
770	            points += 2;
771	        }
772	        if (tenureInFiscalYears(owner) > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
773	            points += 3;
774	        }
775	        return points;
776	    }
