778	    /**
779	     * Maps {@code membershipPoints} to the numeric {@code membershipLevel}: level 1 for 0-1 points,
780	     * 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
781	     */
782	    private static int membershipLevelForPoints(int points) {
783	        if (points <= 1) {
784	            return 1;
785	        }
786	        if (points <= 3) {
787	            return 2;
788	        }
789	        if (points <= 5) {
790	            return 3;
791	        }
792	        return 4;
793	    }
