795	    /**
796	     * Caps a newly computed {@code membershipLevel} so it never exceeds one above the current maximum
797	     * {@code membershipLevel} among the new owner's household members - the existing, non-deleted
798	     * owners already carrying the same {@code householdId}. When the household has no existing member
799	     * (or none with a recorded level) no cap applies and the level is returned unchanged; otherwise the
800	     * level is limited to {@code max(member level) + 1}. The count reflects the state prior to this
801	     * create, as the new owner has not yet been saved.
802	     */
803	    private int capMembershipLevelByHousehold(int membershipLevel, String householdId) {
804	        Integer maxMemberLevel = null;
805	        for (Owner existing : this.clinicService.findAllOwners()) {
806	            if (existing.isDeleted()) {
807	                continue;
808	            }
809	            if (!householdId.equals(existing.getHouseholdId())) {
810	                continue;
811	            }
812	            Integer existingLevel = existing.getMembershipLevel();
813	            if (existingLevel == null) {
814	                continue;
815	            }
816	            if (maxMemberLevel == null || existingLevel > maxMemberLevel) {
817	                maxMemberLevel = existingLevel;
818	            }
819	        }
820	        if (maxMemberLevel == null) {
821	            return membershipLevel;
822	        }
823	        return Math.min(membershipLevel, maxMemberLevel + 1);
824	    }
