826	    /**
827	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July fiscal-year boundaries
828	     * crossed between its {@code registrationDate} and the current server date. An owner with no
829	     * registration date, or one dated in the future, has a tenure of zero.
830	     */
831	    private static long tenureInFiscalYears(Owner owner) {
832	        LocalDate registrationDate = owner.getRegistrationDate();
833	        if (registrationDate == null) {
834	            return 0;
835	        }
836	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate));
837	    }
