845	    /**
846	     * Rejects a create whose city already contains {@value #CITY_CAPACITY} or more owners,
847	     * compared case-insensitively - the same way the city is matched when deriving the owner's
848	     * region. The count reflects the state prior to this create. A city
849	     * at capacity is reported via {@link CityAtCapacityException}, which the exception handler
850	     * translates to a 409.
851	     */
852	    private void rejectCityAtCapacity(String city) {
853	        int count = 0;
854	        for (Owner existing : this.clinicService.findAllOwners()) {
855	            if (city.equalsIgnoreCase(existing.getCity())) {
856	                count++;
857	            }
