872	    /**
873	     * Computes the {@code capacityWarning} for a create in the given city: true when the city
874	     * already holds between {@value #CITY_CAPACITY_WARNING_THRESHOLD} and
875	     * {@value #CITY_CAPACITY} (exclusive) owners - approaching the hard capacity limit - otherwise
876	     * false. The city is matched case-insensitively and the count reflects the state prior to this
877	     * create, exactly as {@link #rejectCityAtCapacity(String)} accumulates it.
878	     */
879	    private boolean capacityWarningFor(String city) {
880	        int count = 0;
881	        for (Owner existing : this.clinicService.findAllOwners()) {
882	            if (city.equalsIgnoreCase(existing.getCity())) {
883	                count++;
884	            }
885	        }
886	        return count >= CITY_CAPACITY_WARNING_THRESHOLD && count < CITY_CAPACITY;
