889	    /**
890	     * The maximum number of owners that may be created on any single day (by
891	     * {@code registrationDate}). A create attempted once this many owners already carry the
892	     * current day's registration date is rejected.
893	     */
894	    private static final int DAILY_OWNER_LIMIT = 100;
