896	    /**
897	     * Rejects a create once {@value #DAILY_OWNER_LIMIT} or more owners already carry the given
898	     * business-day-adjusted {@code registrationDate} (the date the new owner will itself receive).
899	     * The count reflects the state prior to this create. When the limit is reached the create is
900	     * reported via {@link DailyOwnerLimitExceededException}, which the exception handler translates
901	     * to a 429 Too Many Requests.
902	     */
903	    private void rejectDailyOwnerLimit(LocalDate registrationDate) {
904	        int count = 0;
905	        for (Owner existing : this.clinicService.findAllOwners()) {
906	            if (registrationDate.equals(existing.getRegistrationDate())) {
907	                count++;
908	            }
909	        }
910	        if (count >= DAILY_OWNER_LIMIT) {
911	            throw new DailyOwnerLimitExceededException();
912	        }
913	    }
914	
915	    /**
916	     * The number of owners that must already carry a given {@code registrationDate} before a
917	     * create on that date is flagged with a bulk-signup warning. Once <em>more than</em> this
918	     * many owners already exist for the day, the new owner's {@code bulkSignupWarning} is true.
919	     */
920	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
921	
922	    /**
923	     * Computes the {@code bulkSignupWarning} for a create on the given business-day-adjusted
924	     * {@code registrationDate}: true when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners
925	     * have already been created for that date, otherwise false. The count reflects the state prior
926	     * to this create, matching how the daily-limit rule accumulates.
927	     */
928	    private boolean bulkSignupWarningFor(LocalDate registrationDate) {
929	        int count = 0;
930	        for (Owner existing : this.clinicService.findAllOwners()) {
931	            if (registrationDate.equals(existing.getRegistrationDate())) {
932	                count++;
933	            }
934	        }
935	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
936	    }
937	
938	    /**
939	     * Rolls an effective registration date forward onto a business day. A Saturday, Sunday or listed
940	     * public holiday is advanced to the next non-holiday business day; a plain weekday is returned
941	     * unchanged. This is applied to the effective registration date - whether supplied in the request
942	     * or defaulted to the server date - so the stored {@code registrationDate}, and everything derived
943	     * from it, always falls on a business day.
944	     */
945	    /**
946	     * Rejects a supplied {@code registrationDate} that lies in the future. A registration date is
947	     * only ever explicitly supplied on the request; when present it must not be later than the
948	     * current server date. A future date raises a {@link FutureRegistrationDateException}, which the
949	     * exception handler translates to a 400 Bad Request. A {@code null} date (the default, filled in
950	     * later from the server date) is accepted.
951	     */
952	    private static void rejectFutureRegistrationDate(LocalDate registrationDate) {
953	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
954	            throw new FutureRegistrationDateException(registrationDate);
955	        }
956	    }
957	
958	    /**
959	     * The fixed list of public holidays. An effective registration date that lands on any of these
960	     * is rolled forward, together with weekends, to the next non-holiday business day.
961	     */
962	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
963	        LocalDate.of(2026, 1, 1),
964	        LocalDate.of(2026, 1, 26),
965	        LocalDate.of(2026, 4, 25),
966	        LocalDate.of(2026, 12, 25),
967	        LocalDate.of(2026, 12, 28));
968	
969	    private static LocalDate toBusinessDay(LocalDate date) {
970	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
971	            date = date.plusDays(1);
972	        }
973	        return date;
974	    }
975	
976	    private static boolean isWeekend(LocalDate date) {
977	        return switch (date.getDayOfWeek()) {
978	            case SATURDAY, SUNDAY -> true;
979	            default -> false;
980	        };
981	    }
982	
983	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
984	    @Override
985	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
986	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
987	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
988	            OwnerDto replay = idempotentCreates.get(idempotencyKey);
989	            if (replay != null) {
990	                return new ResponseEntity<>(replay, HttpStatus.OK);
991	            }
992	        }
993	        String normalizedLine1 = null;
994	        String normalizedLine2 = null;
995	        String composedAddress;
996	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
997	            normalizedLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
998	            if (!isBlank(ownerFieldsDto.getAddressLine2())) {
999	                normalizedLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
1000	            }
1001	            composedAddress = normalizedLine2 == null
1002	                ? normalizedLine1
1003	                : normalizedLine1 + " " + normalizedLine2;
1004	        } else {
1005	            composedAddress = normalizeAddress(ownerFieldsDto.getAddress());
1006	        }
1007	        rejectMissingOrBlankFields(ownerFieldsDto, composedAddress);
1008	        rejectCityAtCapacity(ownerFieldsDto.getCity());
1009	        HttpHeaders headers = new HttpHeaders();
1010	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
1011	        owner.setAddress(composedAddress);
1012	        owner.setAddressLine1(normalizedLine1);
1013	        owner.setAddressLine2(normalizedLine2);
1014	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
1015	        owner.setTelephone(normalizedTelephone);
1016	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
1017	        owner.setEmail(normalizedEmail);
1018	        validatePostcode(owner.getCity(), owner.getPostcode());
1019	        String householdId = householdIdFor(owner.getLastName(), owner.getPostcode());
1020	        rejectDuplicateIdentity(normalizedTelephone, normalizedEmail, owner.getLastName());
1021	        rejectFutureRegistrationDate(owner.getRegistrationDate());
1022	        LocalDate effectiveDate = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
1023	        LocalDate registrationDate = toBusinessDay(effectiveDate);
1024	        rejectDailyOwnerLimit(registrationDate);
1025	        owner.setBulkSignupWarning(bulkSignupWarningFor(registrationDate));
1026	        owner.setCapacityWarning(capacityWarningFor(owner.getCity()));
1027	        owner.setRegistrationDate(registrationDate);
1028	        String region = deriveRegion(owner.getCity(), owner.getPostcode());
1029	        owner.setMemberId(deduplicateMemberId(
1030	            memberIdFor(region, owner.getRegistrationDate(), normalizedTelephone, owner.getLastName())));
1031	        owner.setHouseholdId(householdId);
1032	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
1033	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
1034	        int membershipPoints = membershipPointsFor(owner);
1035	        owner.setMembershipPoints(membershipPoints);
1036	        int membershipLevel = membershipLevelForPoints(membershipPoints);
1037	        // A declared household member (sharesHousehold) keeps its point-derived level; an owner
1038	        // admitted into an existing household implicitly has its level capped one above the
1039	        // household's current maximum.
1040	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
1041	            membershipLevel = capMembershipLevelByHousehold(membershipLevel, owner.getHouseholdId());
1042	        }
1043	        owner.setMembershipLevel(membershipLevel);
1044	        Integer possibleDuplicateOf = findPossibleDuplicateOf(ownerFieldsDto, normalizedTelephone, normalizedEmail);
1045	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
1046	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
1047	        this.clinicService.saveOwner(owner);
1048	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
1049	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
1050	        emitOwnerCreatedEvent(owner);
1051	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
1052	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
1053	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
1054	            idempotentCreates.put(idempotencyKey, ownerDto);
1055	        }
1056	        headers.setLocation(UriComponentsBuilder.newInstance()
1057	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
1058	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
1059	    }
1060	
1061	    /**
1062	     * Emits the immutable {@code OWNER_CREATED} structured event to the {@code AUDIT} logger as a
1063	     * JSON object {@code {seq, ownerId, memberId, membershipLevel, event}}. The {@code seq} is a
1064	     * per-application monotonically increasing integer that totally orders creates, and
1065	     * {@code memberId} carries the owner's current primary identifier
1066	     * ({@link #primaryIdentifierOf}). This is a distinct line from the human-readable audit line.
1067	     */
1068	    private void emitOwnerCreatedEvent(Owner owner) {
1069	        Map<String, Object> event = new LinkedHashMap<>();
1070	        event.put("seq", OWNER_EVENT_SEQ.incrementAndGet());
1071	        event.put("ownerId", owner.getId());
1072	        event.put("memberId", primaryIdentifierOf(owner));
1073	        event.put("membershipLevel", owner.getMembershipLevel());
1074	        event.put("event", "OWNER_CREATED");
1075	        AUDIT.info(EVENT_MAPPER.writeValueAsString(event));
1076	    }
1077	
1078	    /**
1079	     * The owner's current primary identifier carried by the {@code OWNER_CREATED} event: the unified
1080	     * {@code memberId} into which the former {@code customerCode} has been consolidated.
1081	     */
1082	    private static String primaryIdentifierOf(Owner owner) {
1083	        return owner.getMemberId();
1084	    }
1085	
1086	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
1087	    @Override
1088	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
