254	     * the remaining consonants (b/f/p/v->1, c/g/j/k/q/s/x/z->2, d/t->3, l->4, m/n->5, r->6), with
255	     * adjacent duplicate codes collapsed, vowels (and y) resetting the run, and h/w transparent. The
256	     * result is padded with zeros to exactly four characters. A null or letterless name yields "".
257	     */
258	    private static String soundex(String name) {
259	        if (name == null) {
260	            return "";
261	        }
262	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
263	        if (letters.isEmpty()) {
264	            return "";
265	        }
266	        StringBuilder code = new StringBuilder();
267	        code.append(letters.charAt(0));
268	        char prev = soundexCode(letters.charAt(0));
269	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
270	            char c = letters.charAt(i);
271	            if (c == 'H' || c == 'W') {
272	                continue;
273	            }
274	            char digit = soundexCode(c);
275	            if (digit != '0' && digit != prev) {
276	                code.append(digit);
277	            }
278	            prev = digit;
279	        }
280	        while (code.length() < 4) {
281	            code.append('0');
282	        }
283	        return code.toString();
284	    }
