288	     */
289	    private static char soundexCode(char c) {
290	        return switch (c) {
291	            case 'B', 'F', 'P', 'V' -> '1';
292	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
293	            case 'D', 'T' -> '3';
294	            case 'L' -> '4';
295	            case 'M', 'N' -> '5';
