    String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
    for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
        if (domain.endsWith("." + disposable)) {
            return true;
        }
    }
    return false;
}

